<?php
class EmailService
{
    private $pdo;
    private $config;
    public function __construct($pdo,$config=array()){$this->pdo=$pdo;$this->config=$config;}
    public function settings(){
        $keys=array('smtp_enabled','smtp_host','smtp_port','smtp_encryption','smtp_username','smtp_password','smtp_from_email','smtp_from_name');
        $s=$this->pdo->prepare('SELECT * FROM system_settings WHERE setting_key IN ('.implode(',',array_fill(0,count($keys),'?')).')');$s->execute($keys);$rows=array();foreach($s as $r)$rows[$r['setting_key']]=$r;
        $password='';if(!empty($rows['smtp_password']['setting_ciphertext'])){try{$password=(new CryptoService($this->config))->decrypt($rows['smtp_password']['setting_ciphertext'],$rows['smtp_password']['setting_nonce'],$rows['smtp_password']['setting_tag']);}catch(Throwable $e){$password='';}}
        return array('enabled'=>isset($rows['smtp_enabled']['setting_value'])&&$rows['smtp_enabled']['setting_value']==='1','host'=>trim(isset($rows['smtp_host']['setting_value'])?$rows['smtp_host']['setting_value']:''),'port'=>(int)(isset($rows['smtp_port']['setting_value'])?$rows['smtp_port']['setting_value']:587),'encryption'=>strtolower(isset($rows['smtp_encryption']['setting_value'])?$rows['smtp_encryption']['setting_value']:'tls'),'username'=>isset($rows['smtp_username']['setting_value'])?$rows['smtp_username']['setting_value']:'','password'=>$password,'from_email'=>isset($rows['smtp_from_email']['setting_value'])?$rows['smtp_from_email']['setting_value']:'','from_name'=>isset($rows['smtp_from_name']['setting_value'])?$rows['smtp_from_name']['setting_value']:'','configured'=>trim(isset($rows['smtp_host']['setting_value'])?$rows['smtp_host']['setting_value']:'')!==''&&filter_var(isset($rows['smtp_from_email']['setting_value'])?$rows['smtp_from_email']['setting_value']:'',FILTER_VALIDATE_EMAIL)&&$password!=='');
    }
    public function saveSettings($input,$adminId=null){
        if(!is_array($input))throw new InvalidArgumentException('SMTP 设置格式无效。');
        $enabled=!empty($input['enabled'])||(!empty($input['smtp_enabled'])&&$input['smtp_enabled']==='1');
        $host=trim(isset($input['host'])?$input['host']:(isset($input['smtp_host'])?$input['smtp_host']:''));$port=(int)(isset($input['port'])?$input['port']:(isset($input['smtp_port'])?$input['smtp_port']:587));$encryption=strtolower(trim(isset($input['encryption'])?$input['encryption']:(isset($input['smtp_encryption'])?$input['smtp_encryption']:'tls')));$username=trim(isset($input['username'])?$input['username']:(isset($input['smtp_username'])?$input['smtp_username']:''));$fromEmail=trim(isset($input['from_email'])?$input['from_email']:(isset($input['smtp_from_email'])?$input['smtp_from_email']:''));$fromName=trim(isset($input['from_name'])?$input['from_name']:(isset($input['smtp_from_name'])?$input['smtp_from_name']:''));$password=isset($input['password'])?(string)$input['password']:(isset($input['smtp_password'])?(string)$input['smtp_password']:'');
        if($host===''||strlen($host)>255||$port<1||$port>65535||!in_array($encryption,array('none','tls','ssl'),true)||!filter_var($fromEmail,FILTER_VALIDATE_EMAIL)||strlen($fromName)>200)throw new InvalidArgumentException('SMTP 设置无效。');
        $now=date('Y-m-d H:i:s');$values=array('smtp_enabled'=>$enabled?'1':'0','smtp_host'=>$host,'smtp_port'=>(string)$port,'smtp_encryption'=>$encryption,'smtp_username'=>$username,'smtp_from_email'=>$fromEmail,'smtp_from_name'=>$fromName);$this->pdo->beginTransaction();try{foreach($values as $key=>$value)$this->pdo->prepare('INSERT INTO system_settings(setting_key,setting_value,updated_by,updated_at) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by),updated_at=VALUES(updated_at)')->execute(array($key,$value,$adminId,$now));if($password!==''){$c=(new CryptoService($this->config))->encrypt($password);$this->pdo->prepare('INSERT INTO system_settings(setting_key,setting_value,setting_ciphertext,setting_nonce,setting_tag,is_secret,updated_by,updated_at) VALUES("smtp_password","",?,?,?,1,?,?) ON DUPLICATE KEY UPDATE setting_value="",setting_ciphertext=VALUES(setting_ciphertext),setting_nonce=VALUES(setting_nonce),setting_tag=VALUES(setting_tag),is_secret=1,updated_by=VALUES(updated_by),updated_at=VALUES(updated_at)')->execute(array($c[0],$c[1],$c[2],$adminId,$now));}$this->pdo->commit();}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}return true;
    }
    public function sendTest($recipient){$cfg=$this->settings();if(!$cfg['enabled'])throw new RuntimeException('SMTP 未启用。');if($cfg['host']===''||!filter_var($cfg['from_email'],FILTER_VALIDATE_EMAIL)||$cfg['password']==='')throw new RuntimeException('SMTP 尚未完整配置。');return $this->send($recipient,'SMTP 测试邮件','这是 SMTP 配置测试邮件。');}
    public function send($to,$subject,$body){
        $cfg=$this->settings();if(!$cfg['enabled'])return false;if(!filter_var($to,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('收件地址无效。');if($cfg['host']===''||!filter_var($cfg['from_email'],FILTER_VALIDATE_EMAIL))throw new RuntimeException('SMTP 尚未完整配置。');
        $transport=($cfg['encryption']==='ssl'?'ssl://':'').$cfg['host'].':'.$cfg['port'];$errno=0;$err='';$fp=@stream_socket_client($transport,$errno,$err,8,STREAM_CLIENT_CONNECT);if(!$fp)throw new RuntimeException('SMTP 网络连接失败。');stream_set_timeout($fp,8);$this->expect($fp,220);$this->command($fp,'EHLO localhost',250);if($cfg['encryption']==='tls'){$this->command($fp,'STARTTLS',220);if(!stream_socket_enable_crypto($fp,true,STREAM_CRYPTO_METHOD_TLS_CLIENT))throw new RuntimeException('SMTP TLS 握手失败。');$this->command($fp,'EHLO localhost',250);}if($cfg['username']!==''){$this->command($fp,'AUTH LOGIN',334);$this->command($fp,base64_encode($cfg['username']),334);$this->command($fp,base64_encode($cfg['password']),235);}$this->command($fp,'MAIL FROM:<'.$cfg['from_email'].'>',250);$this->command($fp,'RCPT TO:<'.$to.'>',250);$this->command($fp,'DATA',354);$name=$cfg['from_name']!==''?'=?UTF-8?B?'.base64_encode($cfg['from_name']).'?=':'';$headers="From: ".($name?$name.' ':'')."<".$cfg['from_email'].">\r\nTo: <".$to.">\r\nSubject: =?UTF-8?B?".base64_encode($subject)."?=\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: 8bit\r\n\r\n";$body=str_replace("\n","\r\n",str_replace("\r\n","\n",(string)$body));$body=preg_replace('/^\./m','..',$body);$this->command($fp,$headers.$body."\r\n.",250);$this->command($fp,'QUIT',221);fclose($fp);return true;
    }
    private function command($fp,$cmd,$code){fwrite($fp,$cmd."\r\n");$this->expect($fp,$code);}
    private function expect($fp,$code){$line='';while(($part=fgets($fp,512))!==false){$line.=$part;if(strlen($part)<4||$part[3]!=='-')break;}if((int)substr($line,0,3)!==$code)throw new RuntimeException('SMTP 响应异常。');}
}
